   Profile=profile;string n=Guid.NewGuid().ToString("N"),boot=ProtectedAttempt.CurrentBoot(),drive=Path.GetPathRoot(Environment.SystemDirectory),parent=Path.Combine(drive,"rpc-lifecycle-ci-"+n),root=Path.Combine(parent,n);DirectoryNew(parent);DirectoryNew(root);Put(Path.Combine(root,"entry.exe"),image);long now=BoundedWorker.MonotonicMilliseconds();
   if(original==null){string id=Guid.NewGuid().ToString("N"),pp=Path.Combine(drive,"rpc-lifecycle-plan-"+id),pr=Path.Combine(pp,id);DirectoryNew(pp);DirectoryNew(pr);
    P=new NativeRpcDefinitionPlan(id,boot,new string('c',32),"rpc"+new string('d',32),"0x"+new string('e',64),new string('f',64),new string('a',64),new string('b',64),new string('c',64),new string('d',64),new string('e',64),pr,now,now+900000,new string('f',64),new string('a',64),ProtectedAttempt.Hash(image));PlanPath=Path.Combine(pr,"native-definition-plan.txt");Put(PlanPath,Encoding.UTF8.GetBytes(P.Encode()));
   }else{P=original.P;PlanPath=original.PlanPath;}
   long end=(profile=="native-lifecycle"?P.Deadline+30000:now+20000)+endDelta;string schema=profile=="native-lifecycle"?"owned-native-rpc-lifecycle-v1":profile=="native-start"?"owned-native-rpc-start-worker-v1":"owned-native-rpc-cleanup-worker-v1",op=profile=="native-lifecycle"?"watch":profile=="native-start"?"start":"stop";
   byte[] raw=Encoding.UTF8.GetBytes(String.Join("\n",new[]{schema,n,boot,now.ToString(),end.ToString(),ProtectedAttempt.Hash(image),op,PlanPath,P.Digest,""}));Contract=Path.Combine(root,"contract.txt");Hash=ProtectedAttempt.Hash(raw);Put(Contract,raw);
  }
  internal ProtectedAttempt Lease(){return Profile=="native-lifecycle"?ProtectedAttempt.PinNativeLifecycleController(Contract,Hash):Profile=="native-start"?ProtectedAttempt.PinNativeStartController(Contract,Hash):ProtectedAttempt.PinNativeCleanupController(Contract,Hash);}
  internal ProtectedAttempt Journal(ProtectedAttempt lease){return Profile=="native-lifecycle"?ProtectedAttempt.PinNativeLifecycleJournalController(PlanPath,P.Digest,lease):Profile=="native-start"?ProtectedAttempt.PinNativeStartJournalController(PlanPath,P.Digest,lease):ProtectedAttempt.PinNativeCleanupJournalController(PlanPath,P.Digest,lease);}
 }
 static void Finished(NativeLifecycleWatch w){Check(w.Done.WaitOne(2000)&&w.Failure==null);}
 public static int Main(string[] args){try{
  var timer=new Timer(delegate{TerminateProcess(GetCurrentProcess(),125);},null,20000,Timeout.Infinite);
  if(args.Length==1&&args[0]=="--inert-owner"){Thread.Sleep(5000);return 0;}if(args.Length!=0)return 64;
  BoundedWorker.EnterSupervisorEnvelope(256UL*1024*1024);image=File.ReadAllBytes(System.Reflection.Assembly.GetExecutingAssembly().Location);
  Test("independent deadline dispatch proceeds while caller is blocked",()=>{long n=BoundedWorker.MonotonicMilliseconds(),at=0;int calls=0;var w=new NativeLifecycleWatch(n,n+150,BoundedWorker.MonotonicMilliseconds,()=>false,r=>{Interlocked.Increment(ref calls);Interlocked.Exchange(ref at,BoundedWorker.MonotonicMilliseconds());});Thread.Sleep(300);Finished(w);Check(calls==1&&w.Reason=="original-deadline"&&at>=n+150&&at<n+1000);Console.WriteLine("deadline callback ms="+(at-n));});
  Test("actual held original process death triggers independent dispatch before deadline",()=>{string exe=System.Reflection.Assembly.GetExecutingAssembly().Location;using(var child=Process.Start(new ProcessStartInfo(exe,"--inert-owner"){UseShellExecute=false,CreateNoWindow=true})){IntPtr held=child.Handle;long creation=child.StartTime.ToUniversalTime().ToFileTimeUtc(),n=BoundedWorker.MonotonicMilliseconds(),at=0;int calls=0;var w=new NativeLifecycleWatch(n,n+1500,BoundedWorker.MonotonicMilliseconds,()=>child.HasExited,r=>{calls++;at=BoundedWorker.MonotonicMilliseconds();});child.Kill();Check(child.WaitForExit(1000));Finished(w);Check(calls==1&&w.Reason=="original-worker-failure"&&at<n+1500);Console.WriteLine("exact inert owner pid="+child.Id+" creation="+creation+" exited="+child.HasExited+" callback ms="+(at-n));GC.KeepAlive(held);}});
  Test("observation failure dispatches cleanup rather than silently ending watch",()=>{long n=BoundedWorker.MonotonicMilliseconds();int calls=0;var w=new NativeLifecycleWatch(n,n+1000,BoundedWorker.MonotonicMilliseconds,delegate{throw new IOException("Injected observation loss");},r=>calls++);Finished(w);Check(calls==1&&w.Reason=="peer-observation-failure");});
  Test("failed cleanup callback remains one-shot with no retry",()=>{long n=BoundedWorker.MonotonicMilliseconds();int calls=0;var w=new NativeLifecycleWatch(n,n+1000,BoundedWorker.MonotonicMilliseconds,()=>true,delegate{calls++;throw new IOException("Injected dispatch ambiguity");});Check(w.Done.WaitOne(1000)&&w.Failure!=null&&calls==1);Thread.Sleep(30);Check(calls==1);});
  Test("rollback closes original watch without resetting time",()=>{long clock=2000;int calls=0;var w=new NativeLifecycleWatch(1000,5000,()=>Interlocked.Read(ref clock),()=>false,r=>calls++);Interlocked.Exchange(ref clock,1500);Finished(w);Check(calls==1&&w.Reason=="clock-rollback");});
  Test("invalid expired future overflow and extended watch windows refuse before dispatch",()=>{foreach(long[] a in new[]{new[]{-1L,1000L,0L},new[]{1000L,1000L,1000L},new[]{1000L,901001L,2000L},new[]{1000L,2000L,2000L},new[]{1000L,2000L,999L},new[]{Int64.MaxValue-1,Int64.MinValue,0L}})Refuse(()=>new NativeLifecycleWatch(a[0],a[1],()=>a[2],()=>false,r=>{throw new Exception("Must not dispatch");}));});
  Test("actual protected start journal cannot forge lifecycle or stop authority",()=>{var c=new Fixture("native-start");using(var l=c.Lease())using(var p=c.Journal(l)){var j=new NativeRpcCleanupJournal(p);foreach(string n in new[]{"native-start.intent","native-start.submit","native-start.invoke","native-start.receipt","native-start.job","native-start.terminal","native-start.observed","native-start.registration","native-device.observed"}){j.WriteOnce(n,"fixture");Check(j.Read(n)=="fixture");Refuse(()=>j.WriteOnce(n,"again"));}foreach(string n in new[]{"native-lifecycle.armed","native-lifecycle.bound","native-start.workers","native-stop.intent","native-definition.intent","native-read.submit"})Refuse(()=>j.WriteOnce(n,"forbidden"));}});
  Test("actual lifecycle journal can bind peers but cannot invoke start or stop",()=>{var c=new Fixture("native-lifecycle");using(var l=c.Lease())using(var p=c.Journal(l)){var j=new NativeRpcCleanupJournal(p);foreach(string n in new[]{"native-lifecycle.armed","native-lifecycle.bound","native-lifecycle.stop","native-lifecycle.result","native-start.workers"}){j.WriteOnce(n,"fixture");Check(j.Read(n)=="fixture");Refuse(()=>j.WriteOnce(n,"again"));}foreach(string n in new[]{"native-start.intent","native-start.submit","native-start.invoke","native-start.receipt","native-start.registration","native-stop.intent","native-stop.receipt","native-definition.intent"})Refuse(()=>j.WriteOnce(n,"forbidden"));}});
  Test("actual start custody pins original lifecycle contract boot image and deadline",()=>{var keeper=new Fixture("native-lifecycle");var worker=new Fixture("native-start",keeper);using(var l=worker.Lease())using(var p=worker.Journal(l)){string token=p.PinLifecycleEvidence(keeper.Contract,keeper.Hash);using(var k=keeper.Lease())Check(token==k.Token);Refuse(()=>p.PinLifecycleEvidence(keeper.Contract,new string('0',64)));var other=new Fixture("native-lifecycle");Refuse(()=>p.PinLifecycleEvidence(other.Contract,other.Hash));}});
  Test("actual lifecycle journal rejects altered cleanup endpoint and cross-profile lease",()=>{var c=new Fixture("native-lifecycle",null,-1);using(var l=c.Lease())Refuse(()=>c.Journal(l));c=new Fixture("native-start");using(var l=c.Lease())Refuse(()=>ProtectedAttempt.PinNativeLifecycleJournalController(c.PlanPath,c.P.Digest,l));});
  Test("actual keeper pins only original start worker contract and rejects foreign attempt",()=>{var keeper=new Fixture("native-lifecycle");var worker=new Fixture("native-start",keeper);using(var l=keeper.Lease())using(var p=keeper.Journal(l)){using(var a=worker.Lease())Check(p.PinNativeStartGroup(worker.Contract,worker.Hash)==a.Token);var foreign=new Fixture("native-start");Refuse(()=>p.PinNativeStartGroup(foreign.Contract,foreign.Hash));}});
  Test("native peer identity refuses actual non-SYSTEM process without bypass",()=>{using(var who=WindowsIdentity.GetCurrent())Check(who.User.Value!="S-1-5-18");using(var self=Process.GetCurrentProcess()){string token=new string('a',128),id=self.Id+","+self.StartTime.ToUniversalTime().ToFileTimeUtc()+","+token+",lifecycle";Refuse(()=>new NativeLifecyclePeer(id,token,"lifecycle",self.MainModule.FileName,0));}});
  Console.WriteLine("COMPLETE "+count+" PASS; watch thread and inert owner process actual; protected administrator namespaces actual; SYSTEM scheduling provider cleanup and VM unqualified");GC.KeepAlive(timer);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
